import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { ordersApi } from '../services/api';

const MyOrders = () => {
    const navigate = useNavigate();
    const [myOrders, setMyOrders] = useState([]);
    const [loading, setLoading] = useState(true);

    // Bộ từ điển dịch trạng thái đơn hàng sang tiếng Việt cho thân thiện
    const statusMap = {
        "Pending": { label: "Chờ xử lý", color: "bg-secondary" },
        "Processing": { label: "Chờ vận chuyển", color: "bg-info" },
        "Shipping": { label: "Đang giao hàng", color: "bg-warning" },
        "Completed": { label: "Đã giao thành công", color: "bg-success" },
        "Cancelled": { label: "Đã hủy", color: "bg-danger" }
    };

    useEffect(() => {
        // Lấy ID khách hàng đang đăng nhập
        const userData = JSON.parse(localStorage.getItem('user') || '{}');
        const currentUserId = userData.userId || userData.id;

        if (!currentUserId) {
            alert("Vui lòng đăng nhập để xem đơn hàng!");
            navigate('/login');
            return;
        }

        // Gọi API lấy danh sách đơn hàng của khách này
        ordersApi.getByUserId(currentUserId)
            .then(res => {
                setMyOrders(res.data || []);
                setLoading(false);
            })
            .catch(err => {
                console.log("Lỗi tải lịch sử đơn hàng: ", err);
                setLoading(false);
            });
    }, [navigate]);

    return (
        <>
            {/* Header rút gọn */}
            <div className="container-fluid page-header py-5">
                <h1 className="text-center text-white display-6">Đơn Hàng Của Tôi</h1>
                <ol className="breadcrumb justify-content-center mb-0">
                    <li className="breadcrumb-item"><Link to="/">Trang chủ</Link></li>
                    <li className="breadcrumb-item active text-white">Lịch sử mua hàng</li>
                </ol>
            </div>

            <div className="container-fluid py-5">
                <div className="container py-5">
                    <h2 className="mb-4">Lịch sử đơn hàng</h2>

                    {loading ? (
                        <h4 className="text-center">Đang tải dữ liệu...</h4>
                    ) : myOrders.length === 0 ? (
                        <div className="text-center py-5">
                            <h4 className="text-secondary">Ní chưa có đơn hàng nào cả! 🛒</h4>
                            <Link to="/shop" className="btn btn-primary mt-3 rounded-pill px-4 py-2 text-white">Đi mua sắm ngay</Link>
                        </div>
                    ) : (
                        <div className="table-responsive">
                            <table className="table table-hover align-middle">
                                <thead className="table-dark">
                                    <tr>
                                        <th scope="col">Mã đơn hàng</th>
                                        <th scope="col">Ngày đặt</th>
                                        <th scope="col">Tổng tiền</th>
                                        <th scope="col">Hình thức thanh toán</th>
                                        <th scope="col">Trạng thái</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {myOrders.map((order) => (
                                        <tr key={order.id}>
                                            <td className="fw-bold text-primary">#{order.id.substring(0, 8).toUpperCase()}</td>
                                            <td>{new Date(order.orderDate || order.createdAt).toLocaleDateString('vi-VN')}</td>
                                            <td className="fw-bold">${order.totalAmount?.toFixed(2)}</td>
                                            <td>{order.paymentMethod === 'Cash On Delivery' ? 'Thanh toán khi nhận hàng' : order.paymentMethod}</td>
                                            <td>
                                                <span className={`badge ${statusMap[order.status]?.color || 'bg-secondary'} p-2 rounded-pill`}>
                                                    {statusMap[order.status]?.label || order.status}
                                                </span>
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    )}
                </div>
            </div>
        </>
    );
};

export default MyOrders;
